/**
 * EV charging data for Japan. Currently Hokkaido only, from 北海道のEV・PHV充電器マップ
 * (一般社団法人北海道開発技術センター, https://decnet.or.jp/hokkaido_evphv), data current as of
 * 2026-06-01. The files in ./data are generated by the pipeline in liquidx-ev-map.
 */
import type { Feature, FeatureCollection, Polygon } from 'geojson';

/** Compact row: [lon, lat, name, typeFlags, statusFlags, hours, address, notes]. */
export type ChargerRow = [number, number, string, number, number, string, string, string];

/** typeFlags */
export const TYPE_DC = 1;
export const TYPE_AC200 = 2;
export const TYPE_AC100 = 4;
/** statusFlags */
export const OPEN_24H = 1;
export const CARD_REQUIRED = 2;
export const EMP_NETWORK = 4;
export const TESLA = 8;

export interface Charger {
	id: number;
	lon: number;
	lat: number;
	name: string;
	dc: boolean;
	ac200: boolean;
	ac100: boolean;
	open24h: boolean;
	cardRequired: boolean;
	emp: boolean;
	tesla: boolean;
	hours: string;
	address: string;
	notes: string;
}

export function decodeChargers(rows: ChargerRow[]): Charger[] {
	return rows.map(([lon, lat, name, type, status, hours, address, notes], id) => ({
		id,
		lon,
		lat,
		name,
		dc: !!(type & TYPE_DC),
		ac200: !!(type & TYPE_AC200),
		ac100: !!(type & TYPE_AC100),
		open24h: !!(status & OPEN_24H),
		cardRequired: !!(status & CARD_REQUIRED),
		emp: !!(status & EMP_NETWORK),
		tesla: !!(status & TESLA),
		hours: hours ?? '',
		address: address ?? '',
		notes: notes ?? ''
	}));
}

export function chargeTypes(c: Charger): string[] {
	const kinds: string[] = [];
	if (c.dc) kinds.push('急速 chademo');
	if (c.ac200) kinds.push('200 v');
	if (c.ac100) kinds.push('100 v');
	return kinds;
}

/** The grid as stored: cell centres at lo0 + ix·step, la0 + iy·step; strings for compactness. */
export interface RawGrid {
	lo0: number;
	la0: number;
	step: number;
	nx: number;
	ny: number;
	/** '1' = land, per cell. */
	mask: string;
	/** Comma-separated km to the nearest fast charger, and to the nearest 24h one. */
	dAll: string;
	d24: string;
}

/** Straight-line km from each land cell to the nearest fast charger. NaN over sea. */
export interface DistanceGrid {
	lo0: number;
	la0: number;
	step: number;
	nx: number;
	ny: number;
	all: Float32Array;
	h24: Float32Array;
}

export type Network = 'all' | '24h';

export function decodeGrid(raw: RawGrid): DistanceGrid {
	const parse = (s: string) => {
		const v = Float32Array.from(s.split(','), Number);
		for (let i = 0; i < v.length; i++) if (raw.mask.charCodeAt(i) !== 49) v[i] = NaN;
		return v;
	};
	const { lo0, la0, step, nx, ny } = raw;
	return { lo0, la0, step, nx, ny, all: parse(raw.dAll), h24: parse(raw.d24) };
}

export const distances = (g: DistanceGrid, network: Network) => (network === '24h' ? g.h24 : g.all);

/** Distance at lon/lat from the nearest cell, NaN over sea or off the grid. */
export function distanceAt(g: DistanceGrid, network: Network, lon: number, lat: number): number {
	const ix = Math.round((lon - g.lo0) / g.step);
	const iy = Math.round((lat - g.la0) / g.step);
	if (ix < 0 || iy < 0 || ix >= g.nx || iy >= g.ny) return NaN;
	return distances(g, network)[iy * g.nx + ix];
}

export function landStats(g: DistanceGrid, network: Network) {
	const v = Array.from(distances(g, network))
		.filter((d) => !Number.isNaN(d))
		.sort((a, b) => a - b);
	return {
		median: v[Math.floor(v.length / 2)] ?? 0,
		p90: v[Math.floor(v.length * 0.9)] ?? 0,
		max: v[v.length - 1] ?? 0
	};
}

/** Ground area of one grid cell in km², at the grid's middle latitude. */
export function cellArea(g: DistanceGrid): number {
	const lat = g.la0 + ((g.ny - 1) * g.step) / 2;
	return (g.step * 111) ** 2 * Math.cos((lat * Math.PI) / 180);
}

export interface Blackspot {
	cells: number;
	/** km² */
	area: number;
	/** Worst distance inside, km. */
	max: number;
	lon: number;
	lat: number;
	/** [west, south, east, north], padded by a cell. */
	bounds: [number, number, number, number];
}

/** Contiguous land at least `threshold` km from a charger, largest first (4-connected). */
export function blackspots(g: DistanceGrid, network: Network, threshold: number): Blackspot[] {
	const d = distances(g, network);
	const { nx, ny, step } = g;
	const seen = new Uint8Array(d.length);
	const hit = (i: number) => d[i] >= threshold; // NaN (sea) is never >= anything
	const area = cellArea(g);
	const out: Blackspot[] = [];
	for (let i = 0; i < d.length; i++) {
		if (seen[i] || !hit(i)) continue;
		const stack = [i];
		seen[i] = 1;
		let cells = 0,
			max = 0,
			sx = 0,
			sy = 0,
			x0 = nx,
			x1 = 0,
			y0 = ny,
			y1 = 0;
		while (stack.length) {
			const c = stack.pop()!;
			const cx = c % nx;
			const cy = (c - cx) / nx;
			cells++;
			max = Math.max(max, d[c]);
			sx += cx;
			sy += cy;
			x0 = Math.min(x0, cx);
			x1 = Math.max(x1, cx);
			y0 = Math.min(y0, cy);
			y1 = Math.max(y1, cy);
			for (const [x, y] of [
				[cx + 1, cy],
				[cx - 1, cy],
				[cx, cy + 1],
				[cx, cy - 1]
			]) {
				if (x < 0 || y < 0 || x >= nx || y >= ny) continue;
				const j = y * nx + x;
				if (seen[j] || !hit(j)) continue;
				seen[j] = 1;
				stack.push(j);
			}
		}
		out.push({
			cells,
			area: Math.round(cells * area),
			max,
			lon: g.lo0 + (sx / cells) * step,
			lat: g.la0 + (sy / cells) * step,
			bounds: [
				g.lo0 + (x0 - 1) * step,
				g.la0 + (y0 - 1) * step,
				g.lo0 + (x1 + 1) * step,
				g.la0 + (y1 + 1) * step
			]
		});
	}
	return out.sort((a, b) => b.cells - a.cells);
}

/** Land cells as square polygons carrying both distances, for a MapLibre fill layer. */
export function gridCells(g: DistanceGrid): FeatureCollection<Polygon> {
	const h = g.step / 2;
	const features: Feature<Polygon>[] = [];
	for (let i = 0; i < g.all.length; i++) {
		if (Number.isNaN(g.all[i])) continue;
		const lon = g.lo0 + (i % g.nx) * g.step;
		const lat = g.la0 + Math.floor(i / g.nx) * g.step;
		features.push({
			type: 'Feature',
			properties: { all: g.all[i], h24: g.h24[i] },
			geometry: {
				type: 'Polygon',
				coordinates: [
					[
						[lon - h, lat - h],
						[lon + h, lat - h],
						[lon + h, lat + h],
						[lon - h, lat + h],
						[lon - h, lat - h]
					]
				]
			}
		});
	}
	return { type: 'FeatureCollection', features };
}

/** Per-route gap analysis: fast chargers within 12 km of the route line, km along it. */
export interface Route {
	name: string;
	km: number;
	/** Fast chargers on the route, and the longest gap between them (after which site). */
	n: number;
	gap: number;
	after: string;
	/** The same, counting only chargers open 24 hours. */
	n24: number;
	gap24: number;
	after24: string;
}

export function decodeRoutes(raw: Record<string, Omit<Route, 'name'>>): Route[] {
	return Object.entries(raw).map(([name, r]) => ({ name, ...r }));
}
